import React, { useState } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Alert, TextInput, SafeAreaView, StatusBar, ActivityIndicator, Image } from 'react-native';
import { useNavigation, useRoute } from '@react-navigation/native';
import { Ionicons } from '@expo/vector-icons';
import { LinearGradient } from 'expo-linear-gradient';
import api from '../services/api';

const CheckoutScreen = () => {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const { cartItems, totalAmount } = route.params || { cartItems: [], totalAmount: 0 };
  const [address, setAddress] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('online'); // online, cod

  const handlePayment = async () => {
    if (!address) {
        Alert.alert('Required', 'Please enter delivery address');
        return;
    }
    setIsProcessing(true);
    
    try {
        // 1. Create Order on Backend
        const orderPayload = {
            items: cartItems.map((item: any) => ({ product_id: item.product_id || item.id, quantity: item.quantity })),
            total: totalAmount,
            address: address,
            payment_method: paymentMethod
        };
        
        // Mock API call
        // const response = await api.post('/orders', orderPayload);
        
        // 2. Mock Payment Gateway Interaction (Razorpay/Stripe)
        setTimeout(() => {
            setIsProcessing(false);
            Alert.alert('Success', 'Order placed successfully!', [
                { text: 'OK', onPress: () => navigation.navigate('Orders') }
            ]);
        }, 2000);

    } catch (error) {
        console.error(error);
        Alert.alert('Error', 'Payment failed');
        setIsProcessing(false);
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="dark-content" backgroundColor="#f5f5f5" />
      <ScrollView contentContainerStyle={styles.scrollContent}>
        
        {/* Address Section */}
        <View style={styles.section}>
            <View style={styles.sectionHeader}>
                <Ionicons name="location-outline" size={20} color="#333" />
                <Text style={styles.sectionTitle}>Delivery Address</Text>
            </View>
            <View style={styles.inputContainer}>
                <TextInput 
                   style={styles.input}
                   multiline
                   placeholder="Enter full address (House No, Street, City, Pincode)..."
                   placeholderTextColor="#999"
                   value={address}
                   onChangeText={setAddress}
                />
            </View>
        </View>

        {/* Order Summary */}
        <View style={styles.section}>
            <View style={styles.sectionHeader}>
                <Ionicons name="receipt-outline" size={20} color="#333" />
                <Text style={styles.sectionTitle}>Order Summary</Text>
            </View>
            <View style={styles.summaryRow}>
                <Text style={styles.summaryLabel}>Items Total</Text>
                <Text style={styles.summaryValue}>₹{totalAmount}</Text>
            </View>
            <View style={styles.summaryRow}>
                <Text style={styles.summaryLabel}>Delivery Fee</Text>
                <Text style={styles.freeDelivery}>Free</Text>
            </View>
            <View style={styles.divider} />
            <View style={styles.totalRow}>
                <Text style={styles.totalLabel}>Total to Pay</Text>
                <Text style={styles.totalValue}>₹{totalAmount}</Text>
            </View>
        </View>

        {/* Payment Method */}
        <View style={styles.section}>
            <View style={styles.sectionHeader}>
                <Ionicons name="card-outline" size={20} color="#333" />
                <Text style={styles.sectionTitle}>Payment Method</Text>
            </View>
            
            <TouchableOpacity 
                style={[styles.paymentOption, paymentMethod === 'online' && styles.paymentOptionSelected]}
                onPress={() => setPaymentMethod('online')}
            >
                <View style={[styles.radio, paymentMethod === 'online' && styles.radioSelected]} />
                <Text style={styles.paymentText}>Credit/Debit Card / UPI</Text>
                <Image 
                    source={{uri: 'https://cdn-icons-png.flaticon.com/512/196/196578.png'}} 
                    style={{width: 30, height: 30, marginLeft: 'auto', opacity: 0.7}} 
                    resizeMode="contain"
                />
            </TouchableOpacity>

            <TouchableOpacity 
                style={[styles.paymentOption, paymentMethod === 'cod' && styles.paymentOptionSelected]}
                onPress={() => setPaymentMethod('cod')}
            >
                <View style={[styles.radio, paymentMethod === 'cod' && styles.radioSelected]} />
                <Text style={styles.paymentText}>Cash on Delivery</Text>
                <Ionicons name="cash-outline" size={24} color="#666" style={{marginLeft: 'auto'}} />
            </TouchableOpacity>
        </View>

      </ScrollView>

      {/* Pay Button */}
      <View style={styles.footer}>
        <TouchableOpacity 
          onPress={handlePayment}
          disabled={isProcessing}
        >
            <LinearGradient
                colors={isProcessing ? ['#ccc', '#bbb'] : ['#f59e0b', '#f97316']}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={styles.payButton}
            >
                {isProcessing ? (
                     <ActivityIndicator color="#fff" /> 
                ) : (
                    <>
                        <Text style={styles.payButtonText}>PAY ₹{totalAmount}</Text>
                        <Ionicons name="lock-closed" size={18} color="#fff" style={{marginLeft: 8}} />
                    </>
                )}
            </LinearGradient>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  scrollContent: {
      padding: 15,
      paddingBottom: 100,
  },
  section: {
      backgroundColor: '#fff',
      padding: 15,
      borderRadius: 12,
      marginBottom: 20,
      shadowColor: '#000',
      shadowOffset: { width: 0, height: 1 },
      shadowOpacity: 0.05,
      shadowRadius: 2,
      elevation: 2,
  },
  sectionHeader: {
      flexDirection: 'row',
      alignItems: 'center',
      marginBottom: 15,
      borderBottomWidth: 1,
      borderBottomColor: '#f0f0f0',
      paddingBottom: 10,
  },
  sectionTitle: {
      fontSize: 16,
      fontWeight: '600',
      marginLeft: 10,
      color: '#333',
  },
  inputContainer: {
      backgroundColor: '#f9f9f9',
      borderRadius: 8,
      padding: 10,
      borderWidth: 1,
      borderColor: '#eee',
  },
  input: {
      height: 80,
      textAlignVertical: 'top',
      fontSize: 14,
      color: '#333',
  },
  summaryRow: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      marginBottom: 12,
  },
  summaryLabel: {
      color: '#666',
      fontSize: 14,
  },
  summaryValue: {
      color: '#333',
      fontSize: 14,
      fontWeight: '500',
  },
  freeDelivery: {
      color: '#1e8e3e',
      fontWeight: 'bold',
  },
  divider: {
      height: 1,
      backgroundColor: '#f0f0f0',
      marginVertical: 10,
  },
  totalRow: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      marginTop: 5,
  },
  totalLabel: {
      fontWeight: '700',
      fontSize: 16,
      color: '#333',
  },
  totalValue: {
      fontWeight: '700',
      fontSize: 18,
      color: '#E53935',
  },
  paymentOption: {
      flexDirection: 'row',
      alignItems: 'center',
      padding: 15,
      borderWidth: 1,
      borderColor: '#eee',
      borderRadius: 8,
      marginBottom: 10,
      backgroundColor: '#fff',
  },
  paymentOptionSelected: {
      borderColor: '#f97316',
      backgroundColor: '#fff7ed',
  },
  radio: {
      width: 20,
      height: 20,
      borderRadius: 10,
      borderWidth: 2,
      borderColor: '#ccc',
      marginRight: 10,
  },
  radioSelected: {
      borderColor: '#f97316',
      borderWidth: 5,
  },
  paymentText: {
      fontWeight: '500',
      color: '#333',
      fontSize: 14,
  },
  footer: {
      position: 'absolute',
      bottom: 0,
      left: 0,
      right: 0,
      backgroundColor: '#fff',
      padding: 20,
      borderTopWidth: 1,
      borderTopColor: '#f0f0f0',
      elevation: 10,
  },
  payButton: {
      paddingVertical: 15,
      borderRadius: 30,
      flexDirection: 'row',
      justifyContent: 'center',
      alignItems: 'center',
  },
  payButtonText: {
      color: '#fff',
      fontSize: 16,
      fontWeight: '700',
      letterSpacing: 0.5,
  }
});

export default CheckoutScreen;
